&[data-server-type="rss"] > ul > li:not([data-folder-type], [data-is-busy="true"], [data-has-error="true"]) .icon {
  --icon-color: currentColor;
  fill: var(--icon-color);
}

&[data-folder-type="archive"] > .container > .icon {
  content: var(--icon-archive);
  --icon-color: var(--folder-color-archive);
}

&[data-folder-type="drafts"] > .container > .icon {
  content: var(--icon-draft);
  --icon-color: var(--folder-color-draft);
}

&[data-folder-type="inbox"] > .container > .icon {
  content: var(--icon-inbox);
  --icon-color: var(--account-color, var(--folder-color-inbox));
}

&[data-folder-type="junk"] > .container > .icon {
  content: var(--icon-spam);
